input.command:
python3 - <<'EOF'
import json,glob
for f in glob.glob('~/.claude/projects/*/*.jsonl'):
    for line in open(f):
        try: d=json.loads(line)
        except: continue
        m=d.get('message') or {}
        if m.get('id')=='msg_011CdygtRmd95FeRM1AqU7Xt':
            u=m.get('usage') or {}
            print(d['timestamp'], d.get('requestId'), 'blocks=',len(m.get('content') or []),
                  'out=',u.get('output_tokens'),'cc=',u.get('cache_creation_input_tokens'),
                  'cr=',u.get('cache_read_input_tokens'),'iters=',len(u.get('iterations') or []),
                  'types=',[c.get('type') for c in (m.get('content') or [])])
EOF

