    font-family:"IBM Plex Mono",monospace;font-size:12px;color:var(--ink-3);
    display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}
  :focus-visible{outline:2px solid var(--accent);outline-offset:2px}
