python3 - <<'EOF'
import json,glob
for f in glob.glob('~/.claude/projects/*/*.jsonl'):
    for i,line in enumerate(open(f)):
        if 'CLAUDE_CODE_SUBAGENT_PROMPT_CACHE_TTL' in line and 'DISABLE_INTERLEAVED_THINKING' in line:
            d=json.loads(line)
            print('file:',f.split('/')[-1][:8],'line',i,'type:',d.get('type'))
            print('top keys:',list(d.keys()))
            m=d.get('message') or {}
            c=m.get('content')
            if isinstance(c,list):
                for b in c:
                    print('  block type:',b.get('type'), 'name:',b.get('name'),'tool_use_id:',b.get('tool_use_id'))
            print('toolUseResult keys:', list((d.get('toolUseResult') or {}).keys()) if isinstance(d.get('toolUseResult'),dict) else type(d.get('toolUseResult')))
            s=line
            j=s.find('CLAUDE_CODE_PROMPT_CACHE_TTL')
            print('CONTEXT:', s[max(0,j-700):j+300].replace('\\n','\n')[:1100])
            raise SystemExit
EOF

