python3 - <<'EOF'
import json,re
W='/private/tmp/claude-501/-Users-chrisebert-Code-cache-ttl-analyzer/908ed721-24d1-4bb6-87f0-6e46d882e973/scratchpad/transcript/original.jsonl'
# find the tool_result that contains the cross-session grep dump
for i,line in enumerate(open(W)):
    if 'you work for is almost certainly in it' in line or 'RATIONALE.md' in line:
        d=json.loads(line)
        print('=== line',i,'type',d.get('type'))
        tr=d.get('toolUseResult')
        txt = tr.get('stdout','') if isinstance(tr,dict) else ''
        if not txt:
            m=d.get('message') or {}
            c=m.get('content')
            if isinstance(c,list):
                txt=''.join(b.get('text','') or (b.get('content') if isinstance(b.get('content'),str) else '') for b in c)
        for mm in re.finditer(r'employer|you work for|company|client|RATIONALE|[REDACTED_PROJECT_A]|[REDACTED_PROJECT_A]|[REDACTED_PROJECT_B]|[REDACTED_PROJECT_B]', txt, re.I):
            print('   >>', txt[max(0,mm.start()-260):mm.start()+260].replace('\n',' | '))
            print()
        break
EOF
